import{_ as p,a0 as s,w as n,s as d,I as t,x as o,a1 as a,A as i,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"如何在 Linux 上設置密碼策略 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上設置密碼策略 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上設置密碼策略 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上設置密碼策略 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/How to set password policy on Linux","title":"如何在 Linux 上設置密碼策略","tag":"201401","desc":""},"relativePath":"201401/How to set password policy on Linux.md","filePath":"[post].md"}'),u={name:"201401/How to set password policy on Linux.md"};function m(c,e,b,x,f,k){const r=s("Link");return n(),d("div",null,[e[15]||(e[15]=t("h1",{id:"如何在-linux-上設置密碼策略",tabindex:"-1"},[o("如何在 Linux 上設置密碼策略 "),t("a",{class:"header-anchor",href:"#如何在-linux-上設置密碼策略","aria-label":"Permalink to “如何在 Linux 上設置密碼策略”"},"​")],-1)),e[16]||(e[16]=t("p",null,[o("用户帳號管理是系統管理員最重要的工作之一。而密碼安全是系統安全中最受關注的一塊。在本教程中，我將為大家介紹"),t("strong",null,"如何在 Linux 上設置密碼策略"),o("。")],-1)),t("p",null,[e[1]||(e[1]=o("假設你已經在你的 Linux 系統上使用了 ",-1)),a(r,{href:"http://www.linux-pam.org/"},{default:i(()=>[...e[0]||(e[0]=[o("PAM (Pluggable Authentication Modules，插入式驗證模組)",-1)])]),_:1}),e[2]||(e[2]=o("，因為這些年所有的 Linux 發行版都在使用它。",-1))]),e[17]||(e[17]=l(`<h3 id="準備工作" tabindex="-1">準備工作 <a class="header-anchor" href="#準備工作" aria-label="Permalink to “準備工作”">​</a></h3><p>安裝 PAM 的 cracklib 模組，cracklib 能提供額外的密碼檢查能力。</p><p>Debian、Ubuntu 或 Linux Mint 系統上：</p><pre><code>$ sudo apt-get install libpam-cracklib 
</code></pre><p>CentOS、Fedora、RHEL 系統已經默認安裝了 cracklib PAM 模組，所以在這些系統上無需執行上面的操作。</p><p>為了強制實施密碼策略，我們需要修改 /etc/pam.d 目錄下的 PAM 配置文件。一旦修改，策略會馬上生效。</p><p>注意：此教程中的密碼策略只對非 root 用户有效，對 root 用户無效。</p><h3 id="禁止使用舊密碼" tabindex="-1">禁止使用舊密碼 <a class="header-anchor" href="#禁止使用舊密碼" aria-label="Permalink to “禁止使用舊密碼”">​</a></h3><p>找到同時有 “password” 和 “pam_unix.so” 字段並且附加有 “remember=5” 的那行，它表示禁止使用最近用過的5個密碼（己使用過的密碼會被保存在 /etc/security/opasswd 下面）。</p><p>Debian、Ubuntu 或 Linux Mint 系統上：</p><pre><code>$ sudo vi /etc/pam.d/common-password 
</code></pre><blockquote><p>password [success=1 default=ignore] pam_unix.so obscure sha512 remember=5</p></blockquote><p>CentOS、Fedora、RHEL 系統上：</p><pre><code>$ sudo vi /etc/pam.d/system-auth 
</code></pre><blockquote><p>password sufficient pam_unix.so sha512 shadow nullok try_first_pass use_authtok remember=5</p></blockquote><h3 id="設置最短密碼長度" tabindex="-1">設置最短密碼長度 <a class="header-anchor" href="#設置最短密碼長度" aria-label="Permalink to “設置最短密碼長度”">​</a></h3><p>找到同時有 “password” 和 “pam_cracklib.so” 字段並且附加有 “minlen=10” 的那行，它表示最小密碼長度為（10 - 類型數量）。這裏的 “類型數量” 表示不同的字符類型數量。PAM 提供4種類型符號作為密碼（大寫字母、小寫字母、數字和標點符號）。如果你的密碼同時用上了這4種類型的符號，並且你的 minlen 設為10，那麼最短的密碼長度允許是6個字符。</p><p>Debian、Ubuntu 或 Linux Mint 系統上：</p><pre><code>$ sudo vi /etc/pam.d/common-password 
</code></pre><blockquote><p>password requisite pam_cracklib.so retry=3 minlen=10 difok=3</p></blockquote><p>CentOS、Fedora、RHEL 系統上：</p><pre><code>$ sudo vi /etc/pam.d/system-auth 
</code></pre><blockquote><p>password requisite pam_cracklib.so retry=3 difok=3 minlen=10</p></blockquote><h3 id="設置密碼複雜度" tabindex="-1">設置密碼複雜度 <a class="header-anchor" href="#設置密碼複雜度" aria-label="Permalink to “設置密碼複雜度”">​</a></h3><p>找到同時有 “password” 和 “pam_cracklib.so” 字段並且附加有 “ucredit=-1 lcredit=-2 dcredit=-1 ocredit=-1” 的那行，它表示密碼必須至少包含一個大寫字母（ucredit），兩個小寫字母（lcredit），一個數字（dcredit）和一個標點符號（ocredit）。</p><p>Debian、Ubuntu 或 Linux Mint 系統上：</p><pre><code>$ sudo vi /etc/pam.d/common-password 
</code></pre><blockquote><p>password requisite pam_cracklib.so retry=3 minlen=10 difok=3 ucredit=-1 lcredit=-2 dcredit=-1 ocredit=-1</p></blockquote><p>CentOS、Fedora、RHEL 系統上：</p><pre><code>$ sudo vi /etc/pam.d/system-auth 
</code></pre><blockquote><p>password requisite pam_cracklib.so retry=3 difok=3 minlen=10 ucredit=-1 lcredit=-2 dcredit=-1 ocredit=-1</p></blockquote><h3 id="設置密碼過期期限" tabindex="-1">設置密碼過期期限 <a class="header-anchor" href="#設置密碼過期期限" aria-label="Permalink to “設置密碼過期期限”">​</a></h3><p>編輯 /etc/login.defs 文件，可以設置當前密碼的有效期限，具體變量如下所示：</p><pre><code>$ sudo vi /etc/login.defs 
</code></pre><blockquote><p>PASS_MAX_DAYS 150 PASS_MIN_DAYS 0 PASS_WARN_AGE 7</p></blockquote><p>這些設置要求用户每6個月改變他們的密碼，並且會提前7天提醒用户密碼快到期了。</p><p>如果你想為每個用户設置不同的密碼期限，使用 chage 命令。下面的命令可以查看某個用户的密碼限期：</p><pre><code>$ sudo chage -l xmodulo 
</code></pre><blockquote><p>Last password change : Dec 30, 2013 Password expires : never Password inactive : never Account expires : never Minimum number of days between password change : 0 Maximum number of days between password change : 99999 Number of days of warning before password expires : 7</p></blockquote><p>默認情況下，用户的密碼永不過期。</p><p>下面的命令用於修改 xmodulo 用户的密碼期限：</p><pre><code>$ sudo chage -E 6/30/2014 -m 5 -M 90 -I 30 -W 14 xmodulo 
</code></pre><p>上面的命令將密碼期限設為2014年6月3日。另外，修改密碼的最短週期為5天，最長週期為90天。密碼過期前14天會發送消息提醒用户，過期後帳號會被鎖住30天。</p>`,43)),t("p",null,[a(r,{href:"http://www.flickr.com/photos/xmodulo/11640903324/"},{default:i(()=>[...e[3]||(e[3]=[t("img",{src:"http://farm4.staticflickr.com/3779/11640903324_474963b7bb.jpg",alt:""},null,-1)])]),_:1})]),e[18]||(e[18]=t("hr",null,null,-1)),t("p",null,[e[5]||(e[5]=o("via: ",-1)),a(r,{href:"http://xmodulo.com/2013/12/set-password-policy-linux.html"},{default:i(()=>[...e[4]||(e[4]=[o("http://xmodulo.com/2013/12/set-password-policy-linux.html",-1)])]),_:1})]),t("p",null,[e[8]||(e[8]=o("譯者：",-1)),a(r,{href:"https://github.com/bazz2"},{default:i(()=>[...e[6]||(e[6]=[o("bazz2",-1)])]),_:1}),e[9]||(e[9]=o(" 校對：",-1)),a(r,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...e[7]||(e[7]=[o("Caroline",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=o("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[o("LCTT",-1)])]),_:1}),e[13]||(e[13]=o(" 原創翻譯，",-1)),a(r,{href:"http://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[o("Linux中國",-1)])]),_:1}),e[14]||(e[14]=o(" 榮譽推出",-1))])])}const g=p(u,[["render",m]]);export{L as __pageData,g as default};
